package com.landportal.security; import com.landportal.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service public class CustomUserDetailsService implements UserDetailsService { final UserRepository repo; public CustomUserDetailsService(UserRepository r){repo=r;} public UserDetails loadUserByUsername(String email){var u=repo.findByEmail(email).orElseThrow(()->new UsernameNotFoundException("User not found"));return User.withUsername(u.getEmail()).password(u.getPasswordHash()).roles(u.getRole().name()).disabled(!u.isActive()).build();} }
